from collections import defaultdict
def revenue_by(orders, field):
    totals = defaultdict(int)
    for row in orders:
        totals[row[field]] += row['amount']
    return dict(totals)

from itertools import groupby
def revenue_by(orders, field):
    key = lambda row: row[field]
    return {k: sum(o['amount'] for o in rows) for k, rows in groupby(sorted(orders, key=key), key=key)}

def revenue_by(orders, field, totals={}):
    for o in orders:
        totals[o[field]] = totals.get(o[field], 0) + o['amount']
    return totals

